        let dir = std::env::temp_dir().join(format!("caliper-lazy-{}-{}", std::process::id(), next_session_id()));
        std::fs::create_dir_all(&dir).expect("temp dir");
        std::fs::write(
            dir.join("Button.tsx"),
            "export function Button(props: { /** Label. */ label: string; size?: 'sm' | 'lg' }) { return null; }\n\
